let composerScene='';
let taskId=null,taskName='未命名样机',dirty=false,filter='all',query='',toastTimer,saved=[];
let legacyTasks=[];try{const data=JSON.parse(localStorage.getItem('studio.tasks.v2')||'[]');if(Array.isArray(data))legacyTasks=data}catch{}
saved=legacyTasks;
let frame,enginePromise,engineResolve,engineReady=false,engineLoading=false,engineSummary={revision:0,count:0},baselineRevision=0,requestSequence=0;
const requests=new Map();
const dbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open('studio.real-mockups',1);request.onupgradeneeded=()=>{const db=request.result;db.createObjectStore('tasks',{keyPath:'id'});db.createObjectStore('summaries',{keyPath:'id'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});
async function loadSummaries(){const db=await dbPromise;const summaries=await new Promise((resolve,reject)=>{const req=db.transaction('summaries').objectStore('summaries').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});const map=new Map(legacyTasks.map(x=>[x.id,x]));summaries.forEach(x=>map.set(x.id,x));saved=[...map.values()].sort((a,b)=>b.updated-a.updated);sideTasks();return saved}
