function confirmReplace(action){if(!dirty){action();return}modal('保留当前任务',`<p>“${esc(taskName)}”有未保存的修改。保存草稿后，可以随时回来继续。</p><div class="dialog-footer"><button class="secondary" id="discard">放弃当前修改</button><button class="primary" id="saveNew" style="margin-left:8px">保存并继续</button></div>`);$('#discard').onclick=()=>{dirty=false;closeModal();action()};$('#saveNew').onclick=async()=>{if(await saveTask()){closeModal();action()}}}
async function startTask(id,name){confirmReplace(async()=>{try{engineLoading=true;taskId=null;taskName=name||`${scenes.find(s=>s.id===id)?.name||'样机'} · 新任务`;location.hash='studio';await engineCall('create',id);baselineRevision=engineSummary.revision;dirty=false;sessionStorage.removeItem('studio.activeTask');}catch(e){toast(e.message)}finally{engineLoading=false;updateTaskHeader()}})}
